body:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Observation record; schema validity alone is never a performance pass. Apply evaluateRun.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "stage",
    "requestedRuns",
    "samples",
    "medians",
    "aggregationLabel"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "stage": {
      "enum": [
        "fixture-regression",
        "preview-diagnostic",
        "release-certification"
      ]
    },
    "requestedRuns": {
      "type": "integer",
      "minimum": 1
    },
    "samples": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "timestamp",
          "fixtureOnly",
          "galleryState",
          "environment",
          "identity",
          "navigation",
          "viewport",
          "policy",
          "networkObservation",
          "resources",
          "metrics",
          "media",
          "duplicateProductScripts",
          "blockingMetric"
        ],
        "properties": {
          "timestamp": {
            "type": "string",
            "minLength": 1
          },
          "fixtureOnly": {
            "type": "boolean"
          },
          "galleryState": {
            "type": "string",
            "minLength": 1
          },
          "environment": {
            "type": "object",
            "additionalProperties": true,
            "required": [
              "kind",
              "theme"
            ],
            "properties": {
              "kind": {
                "enum": [
                  "local-fixture",
                  "preview",
                  "production"
                ]
              },
              "theme": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "name",
                  "verified"
                ],
                "properties": {
                  "id": {
                    "type": [
                      "string",
                      "null"
                    ]
                  },
                  "name": {
                    "type": [
                      "string",
                      "null"
                    ]
                  },
                  "verified": {
                    "type": "boolean"
                  }
                }
              }
            }
          },
          "identity": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "requestedUrl",
              "resolvedUrl",
              "requestedRoute",
              "resolvedRoute",
              "productGid",
              "template"
            ],
            "properties": {
              "requestedUrl": {
                "type": "string",
                "minLength": 1
              },
              "resolvedUrl": {
                "type": "string",
                "minLength": 1
              },
              "requestedRoute": {
                "type": "string",
                "minLength": 1
              },
              "resolvedRoute": {
                "type": "string",
                "minLength": 1
              },
              "productGid": {
                "type": "string",
                "pattern": "^gid://shopify/Product/[0-9]+$"
              },
              "template": {
                "const": "product.machine"
              }
            }
          },
          "navigation": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "completed",
              "status",
              "pageKind",
              "password",
              "challenge"
            ],
            "properties": {
              "completed": {
                "type": "boolean"
              },
              "status": {
                "type": [
                  "integer",
                  "null"
                ]
              },
              "pageKind": {
                "enum": [
                  "product",
                  "error",
                  "password",
                  "challenge",
                  "non-product"
                ]
              },
              "password": {
                "type": "boolean"
              },
              "challenge": {
                "type": "boolean"
              }
            }
          },
          "viewport": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "profile",
              "width",
              "height",
              "deviceScaleFactor"
            ],
            "properties": {
              "profile": {
                "enum": [
                  "mobile",
                  "desktop"
                ]
              },
              "width": {
                "type": "integer",
                "minimum": 1
              },
              "height": {
                "type": "integer",
                "minimum": 1
              },
              "deviceScaleFactor": {
                "type": "number",
                "exclusiveMinimum": 0
              }
            }
          },
          "policy": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "throttling",
              "cache",
              "settleMs",
              "settlePolicy"
            ],
            "properties": {
              "throttling": {
                "type": "object",
                "additionalProperties": true,
                "required": [
                  "id"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "cache": {
                "type": "string",
                "minLength": 1
              },
              "settleMs": {
                "type": "number",
                "minimum": 0
              },
              "settlePolicy": {
                "type": "string",
                "minLength": 1
              }
            }
          },
          "networkObservation": {
            "enum": [
              "complete",
              "missing",
              "unsupported"
            ]
          },
          "resources": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": true,
              "required": [
                "url",
                "type",
                "bytes",
                "status",
                "completed",
                "attribution"
              ],
              "properties": {
                "url": {
                  "type": "string",
                  "minLength": 1
                },
                "type": {
                  "type": "string",
                  "minLength": 1
                },
                "bytes": {
                  "type": "number",
                  "minimum": 0
                },
                "status": {
                  "type": "number"
                },
                "completed": {
                  "type": "boolean"
                },
                "attribution": {
                  "enum": [
                    "native-payment-provider",
                    "preview-tooling",
                    "rhino-theme",
                    "native-trade-theme",
                    "synthetic-fixture-media",
                    "first-party",
                    "synthetic-video-provider",
                    "native-shopify",
                    "third-party",
                    "native-recommendations"
                  ]
                }
              }
            }
          },
          "metrics": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "lcpMs",
              "cls",
              "tbtMs",
              "initialTransferBytes",
              "imageBytes",
              "maxImageBytes",
              "firstScreenMediaBytes",
              "requestCount",
              "immediateVideoIframeCount",
              "autoplayMediaCount",
              "thirdPartyScriptHostCount",
              "synchronousThirdPartyScriptCount"
            ],
            "properties": {
              "lcpMs": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "cls": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "tbtMs": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "initialTransferBytes": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "imageBytes": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "maxImageBytes": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "firstScreenMediaBytes": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "requestCount": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "immediateVideoIframeCount": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "autoplayMediaCount": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "thirdPartyScriptHostCount": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              },
              "synchronousThirdPartyScriptCount": {
                "oneOf": [
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "const": "measured"
                      },
                      "value": {
                        "type": "number",
                        "minimum": 0
                      }
                    }
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "status",
                      "value"
                    ],
                    "properties": {
                      "status": {
                        "enum": [
                          "missing",
                          "unsupported"
                        ]
                      },
                      "value": {
                        "type": "null"
                      }
                    }
                  }
                ]
              }
            }
          },
          "media": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "dimensionsValid",
              "secondaryLazy",
              "firstScreenSources"
            ],
            "properties": {
              "dimensionsValid": {
                "type": "boolean"
              },
              "secondaryLazy": {
                "type": "boolean"
              },
              "firstScreenSources": {
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                }
              }
            }
          },
          "duplicateProductScripts": {
            "type": "integer",
            "minimum": 0
          },
          "blockingMetric": {
            "type": "string",
            "minLength": 1
          },
          "secondaryInspection": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "phase",
              "observation",
              "resources",
              "maxImageBytes"
            ],
            "properties": {
              "phase": {
                "type": "string",
                "minLength": 1
              },
              "observation": {
                "enum": [
                  "complete",
                  "missing"
                ]
              },
              "resources": {
                "type": "array",
                "items": {
                  "type": "object",
                  "additionalProperties": true,
                  "required": [
                    "url",
                    "type",
                    "bytes",
                    "status",
                    "completed",
                    "attribution"
                  ],
                  "properties": {
                    "url": {
                      "type": "string",
                      "minLength": 1
                    },
                    "type": {
                      "type": "string",
                      "minLength": 1
                    },
                    "bytes": {
                      "type": "number",
                      "minimum": 0
                    },
                    "status": {
                      "type": "number"
                    },
                    "completed": {
                      "type": "boolean"
                    },
                    "attribution": {
                      "enum": [
                        "native-payment-provider",
                        "preview-tooling",
                        "rhino-theme",
                        "native-trade-theme",
                        "synthetic-fixture-media",
                        "first-party",
                        "synthetic-video-provider",
                        "native-shopify",
                        "third-party",
                        "native-recommendations"
                      ]
                    }
                  }
                }
              },
              "maxImageBytes": {
                "type": "number",
                "minimum": 0
              }
            }
          }
        }
      }
    },
    "medians": {
      "anyOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "lcpMs",
            "cls",
            "tbtMs",
            "initialTransferBytes",
            "imageBytes",
            "maxImageBytes",
            "firstScreenMediaBytes",
            "requestCount",
            "immediateVideoIframeCount",
            "autoplayMediaCount",
            "thirdPartyScriptHostCount",
            "synchronousThirdPartyScriptCount"
          ],
          "properties": {
            "lcpMs": {
              "type": "number",
              "minimum": 0
            },
            "cls": {
              "type": "number",
              "minimum": 0
            },
            "tbtMs": {
              "type": "number",
              "minimum": 0
            },
            "initialTransferBytes": {
              "type": "number",
              "minimum": 0
            },
            "imageBytes": {
              "type": "number",
              "minimum": 0
            },
            "maxImageBytes": {
              "type": "number",
              "minimum": 0
            },
            "firstScreenMediaBytes": {
              "type": "number",
              "minimum": 0
            },
            "requestCount": {
              "type": "number",
              "minimum": 0
            },
            "immediateVideoIframeCount": {
              "type": "number",
              "minimum": 0
            },
            "autoplayMediaCount": {
              "type": "number",
              "minimum": 0
            },
            "thirdPartyScriptHostCount": {
              "type": "number",
              "minimum": 0
            },
            "synchronousThirdPartyScriptCount": {
              "type": "number",
              "minimum": 0
            }
          }
        },
        {
          "type": "null"
        }
      ]
    },
    "aggregationLabel": {
      "type": "string",
      "minLength": 1
    },
    "authorizationRef": {
      "type": "string",
      "minLength": 1
    },
    "widgetDecisionRef": {
      "type": "string",
      "minLength": 1
    }
  }
}
